insert into public.catalog_releases (release_id, country_code, version, status, data_checked_until, notes, source_notes, road_factor, avg_kmh, road_calibrated, road_note, airport_radius_km) values
  ('IE-1', 'IE', 1, 'bozza', '2026-11-19', 'Catalogo ampliato: città, musei, parchi, natura, aeroporti, stazioni e aree portuali. Coordinate Wikidata e foto Commons con attribuzione. La presenza di un punto di trasporto non conferma servizi attivi, tratte, orari o prezzi. Coordinate portuali riferite all’area, non al molo di imbarco.', '[{"label":"Wikidata: dati strutturati CC0","url":"https://www.wikidata.org/wiki/Wikidata:Licensing","checkedAt":"2026-11-19","license":"CC0-1.0"},{"label":"Ente turistico · Irlanda","url":"https://www.ireland.com/en-gb/","checkedAt":"2026-11-19","note":"Consultato per il contesto e la copertura; testi e immagini non importati"}]'::jsonb, null, null, false, 'Parametri stradali non calibrati per questa nazione. I tempi del configuratore sono indicativi: calcolare i trasferimenti prima di attivare.', null)
